def eulerian_num(n, m):
    """
    Returns the nth Eulerian number with parameter m.

    An Eulerian number is a number in the sequence of numbers which are based on the distribution of the number of combinations of the elements of a set {1, 2, ..., n} that contain each element of the set between 0 and n, or in other words, how many ways are there to order the elements of a set {1, 2, ..., n} to get all the numbers between 0 and n, or in another way of saying, how many different paths are there from 0 to n where 0 is at position 0 and each step is one position to the right.

    Parameters:
    n (int): The number of elements in the set.
    m (int): The parameter value.

    Returns:
    int: The nth Eulerian number with parameter m.

    """
    def to_eulerian(n, m):
        return sum(comb(n, r) for r in range(m, n + 1))

    def comb(n, r):
        return math.factorial(n) / math.factorial(r) / math.factorial(n - r)

    def eulerian_numbers(m):
        eulerian = []
        for n in range(m + 1):
            eulerian.append(to_eulerian(n, m))
        return eulerian

    result = eulerian_numbers(m)[n]
    return result
