def is_Sum_Of_Powers_Of_Two(n):
    """
    Checks whether the given number can be represented as sum of non-zero powers of 2 or not.

    Args:
        n (int): The number to check.

    Returns:
        bool: True if the number can be represented as sum of non-zero powers of 2, False otherwise.
    """
    def is_power_of_two(i):
        return (i & (i - 1)) == 0

    def is_sum_of_powers(i):
        powers = []
        for j in range(i.bit_length() + 1):
            if i >= 2**j:
                powers.append(2**j)

        def dfs(i, subset):
            if i == len(powers):
                return sum(subset) == n
            return dfs(i + 1, subset) or dfs(i + 1, subset + [powers[i]])

        return dfs(0, [])

    return is_sum_of_powers(n)
